#![allow(unexpected_cfgs)]

use sdk::*;
use sdk::signer::Signer;
use sdk::mintable::{Mintable, UnsignedSigner};

#[contracttype]
pub struct TransferAuth {
    pub amount: u64,
}

#[contracttype]
pub struct Payment {
    pub memo: u32,
    pub auth: Signer<TransferAuth>,
}

fn main() {
    // Use the concrete Unsigned types generated by the macro.
    // Qualified-path struct syntax `<T as Trait>::AssocType { .. }` is
    // experimental (feature = "more_qualified_paths"), so we name the
    // generated types directly via their module paths.
    let transfer_unsigned =
        __groundhog_mintable_transfer_auth::TransferAuthUnsigned {
            amount: 100,
        };
    let unsigned = __groundhog_mintable_payment::PaymentUnsigned {
        memo: 42,
        auth: UnsignedSigner {
            consumer: ContractAddress::default(),
            data: transfer_unsigned,
        },
    };

    let _node = <Payment as Mintable>::build_auth_token_node(unsigned);
}
